/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');
const loadInter = makeLoadFont('Inter');
const loadRoboto = makeLoadFont('Roboto');

// Module-level font loading guarantees readiness before frame 0
const { fontFamily: montserratFamily } = loadMontserrat();
const { fontFamily: interFamily } = loadInter();
const { fontFamily: robotoFamily } = loadRoboto();



export type AnimatedLinkSceneProps = Record<string, any>;

const AnimatedLinkScene: React.FC<AnimatedLinkSceneProps> = ({
  backgroundColor1 = "#1a0505",
  backgroundColor2 = "#050000",
  primaryColor = "#ff2a2a",
  accentColor = "#ffcc00",
  textColor = "#ffffff",
  textContent = "LIMITED TIME",
  subtextContent = "OFFER ENDS SOON",
  textContentFontFamily = "Montserrat",
  transparentBackground = false,
  durationInSeconds = 6,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  // Font resolution
  const getFontFamily = () => {
    if (textContentFontFamily === "Montserrat") return montserratFamily;
    if (textContentFontFamily === "Inter") return interFamily;
    return robotoFamily;
  };

  // Parser safety for background
  const bgFill = transparentBackground ? "transparent" : "url(#bgGrad)";

  // --- TIMING CONSTANTS ---
  const CLOCK_ENTRANCE = 5;
  const IMPACT_FRAME = 22;
  const TEXT_ENTRANCE = 25;
  const EXIT_DURATION = 15;
  const totalFrames = fps * durationInSeconds;
  const EXIT_START_FRAME = totalFrames - EXIT_DURATION;

  // --- ANIMATIONS ---

  // 1. Clock Flying Entrance (Spring with overshoot/snap)
  const clockEntrance = spring({
    frame: frame - CLOCK_ENTRANCE,
    fps,
    config: { damping: 11, stiffness: 120, mass: 0.9 },
  });
  
  // Custom Y movement: fly from top, snap to center-aligned position (-120px)
  const clockY = interpolate(clockEntrance, [0, 1], [-height * 0.6, -120 * s]);
  const clockScale = interpolate(clockEntrance, [0, 1], [0.1, 1]);
  const clockOpacity = interpolate(frame - CLOCK_ENTRANCE, [0, 4], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // 2. Rapid Hands Spin
  // Speeds through several rotations before slowing down to a precise stop at 10:10 on impact
  const spinProgress = interpolate(frame - CLOCK_ENTRANCE, [0, IMPACT_FRAME - CLOCK_ENTRANCE], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
    easing: (t) => 1 - Math.pow(1 - t, 3), // Smooth decelerating ease-out
  });
  const minuteHandRotation = interpolate(spinProgress, [0, 1], [0, 1440 + 60]); // Spins 4 times, lands at 60deg (10 min)
  const hourHandRotation = interpolate(spinProgress, [0, 1], [0, 360 + 300]);  // Spins 1 time, lands at 300deg (10 hours)

  // 3. Light Sweep crossing clock on impact
  const sweepProgress = interpolate(
    frame - IMPACT_FRAME,
    [0, 16],
    [-280 * s, 280 * s],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // 4. Text "LIMITED TIME" & "OFFER ENDS SOON" Bounce Entrance
  const textEntrance = spring({
    frame: frame - TEXT_ENTRANCE,
    fps,
    config: { damping: 12, stiffness: 140 },
  });
  const textScale = interpolate(textEntrance, [0, 1], [0.5, 1]);
  const textOpacity = interpolate(frame - TEXT_ENTRANCE, [0, 5], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const textY = interpolate(textEntrance, [0, 1], [300 * s, 210 * s]);
  const subTextY = interpolate(textEntrance, [0, 1], [380 * s, 305 * s]);

  // 5. Urgency Edge Glow Pulsing
  const pulseActive = frame >= IMPACT_FRAME;
  const pulseScale = pulseActive
    ? interpolate(Math.sin((frame - IMPACT_FRAME) * 0.12), [-1, 1], [0.98, 1.05])
    : 1;
  const pulseOpacity = pulseActive
    ? interpolate(Math.sin((frame - IMPACT_FRAME) * 0.12), [-1, 1], [0.25, 0.55])
    : 0;

  // 6. Exit Animation (Premium slide down & fade out)
  const exitProgress = spring({
    frame: frame - EXIT_START_FRAME,
    fps,
    config: { damping: 15, stiffness: 100 },
  });
  const exitY = interpolate(exitProgress, [0, 1], [0, height * 0.8]);
  const exitOpacity = interpolate(exitProgress, [0, 1], [1, 0]);

  // 7. Particle Burst on Impact Helper
  const renderBurst = (startFrame: number, cx: number, cy: number, colors: string[], scaleFactor = 1) => {
    return Array.from({ length: 16 }).map((_, i) => {
      const angle = (i / 16) * Math.PI * 2 + (i % 2 === 0 ? 0.15 : -0.15);
      const p = interpolate(frame - startFrame, [0, 22], [0, 1], {
        extrapolateRight: "clamp",
        extrapolateLeft: "clamp",
      });
      if (p === 0 || p === 1) return null;

      const dist = interpolate(p, [0, 1], [40 * s * scaleFactor, 360 * s * scaleFactor]);
      const length = interpolate(p, [0, 0.25, 1], [0, 60 * s * scaleFactor, 0]);
      const opacity = interpolate(p, [0.5, 1], [1, 0], { extrapolateRight: "clamp" });
      const color = colors[i % colors.length];

      const x = cx + Math.cos(angle) * dist;
      const y = cy + Math.sin(angle) * dist;

      return (
        <line
          key={`burst-${startFrame}-${i}`}
          x1={x}
          y1={y}
          x2={x + Math.cos(angle) * length}
          y2={y + Math.sin(angle) * length}
          stroke={color}
          strokeWidth={9 * s * scaleFactor}
          strokeLinecap="round"
          opacity={opacity}
          style={{ transition: "none" }}
        />
      );
    });
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgFill, overflow: "hidden" }}>
      <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0 }}>
        <defs>
          {/* Dark Dramatic Radial Background Gradient */}
          <radialGradient id="bgGrad" cx="50%" cy="40%" r="75%">
            <stop offset="0%" stopColor={backgroundColor1} />
            <stop offset="100%" stopColor={backgroundColor2} />
          </radialGradient>

          {/* Urgent Glow Filters */}
          <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation={15 * s} result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>

          <filter id="heavyGlow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation={45 * s} result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>

          <filter id="shadow" x="-30%" y="-30%" width="160%" height="160%">
            <feDropShadow dx={0} dy={20 * s} stdDeviation={15 * s} floodOpacity={0.8} floodColor="#000000" />
          </filter>

          {/* Clock Clipping for internal Light Sweep */}
          <clipPath id="clockClip">
            <circle cx={0} cy={0} r={180 * s} />
          </clipPath>
        </defs>

        {/* Global coordinate system centered */}
        <g transform={`translate(${width / 2}, ${height / 2 + exitY})`} opacity={exitOpacity}>

          {/* 1. Background Urgency Pulsing Aura */}
          {pulseActive && (
            <circle
              cx={0}
              cy={-120 * s}
              r={240 * s}
              fill={primaryColor}
              opacity={pulseOpacity}
              transform={`scale(${pulseScale})`}
              filter="url(#heavyGlow)"
              style={{ transition: "none" }}
            />
          )}

          {/* 2. Impact Particles Burst */}
          {frame >= IMPACT_FRAME && renderBurst(IMPACT_FRAME, 0, -120 * s, [primaryColor, accentColor, "#ffffff"], 1.3)}

          {/* 3. Clock Icon Group */}
          <g
            transform={`translate(0, ${clockY}) scale(${clockScale})`}
            opacity={clockOpacity}
            filter="url(#shadow)"
            style={{ transition: "none" }}
          >
            {/* Clock Inner Shadow Area */}
            <circle cx={0} cy={0} r={180 * s} fill="#0d0202" />

            {/* Glowing Accent Outer Bezel Ring */}
            <circle
              cx={0}
              cy={0}
              r={180 * s}
              fill="none"
              stroke={primaryColor}
              strokeWidth={20 * s}
              filter="url(#glow)"
            />

            {/* Solid Front Outer Ring */}
            <circle
              cx={0}
              cy={0}
              r={180 * s}
              fill="none"
              stroke={primaryColor}
              strokeWidth={16 * s}
            />

            {/* Tick Marks (12 divisions) */}
            {Array.from({ length: 12 }).map((_, i) => {
              const angle = (i * 360) / 12;
              const isMajor = i % 3 === 0;
              const r1 = isMajor ? 135 * s : 150 * s;
              const r2 = 162 * s;
              const x1 = Math.cos((angle * Math.PI) / 180) * r1;
              const y1 = Math.sin((angle * Math.PI) / 180) * r1;
              const x2 = Math.cos((angle * Math.PI) / 180) * r2;
              const y2 = Math.sin((angle * Math.PI) / 180) * r2;
              return (
                <line
                  key={`tick-${i}`}
                  x1={x1}
                  y1={y1}
                  x2={x2}
                  y2={y2}
                  stroke={isMajor ? accentColor : "#8c1c1c"}
                  strokeWidth={isMajor ? 7 * s : 4 * s}
                  strokeLinecap="round"
                />
              );
            })}

            {/* Clock Hour Hand */}
            <g transform={`rotate(${hourHandRotation})`}>
              <line
                x1={0}
                y1={0}
                x2={0}
                y2={-90 * s}
                stroke="#ffffff"
                strokeWidth={14 * s}
                strokeLinecap="round"
              />
            </g>

            {/* Clock Minute Hand */}
            <g transform={`rotate(${minuteHandRotation})`}>
              <line
                x1={0}
                y1={0}
                x2={0}
                y2={-130 * s}
                stroke={accentColor}
                strokeWidth={10 * s}
                strokeLinecap="round"
              />
              <circle cx={0} cy={-130 * s} r={7 * s} fill={accentColor} />
            </g>

            {/* Center Cap Pin */}
            <circle cx={0} cy={0} r={18 * s} fill="#ffffff" filter="url(#glow)" />
            <circle cx={0} cy={0} r={10 * s} fill={primaryColor} />

            {/* Light Sweep/Shine crossing over Clock Face on Impact */}
            <g clipPath="url(#clockClip)">
              <rect
                x={-280 * s}
                y={sweepProgress}
                width={560 * s}
                height={75 * s}
                fill="#ffffff"
                opacity={0.4}
                transform="rotate(30)"
                style={{ mixBlendMode: "overlay", transition: "none" }}
              />
            </g>
          </g>

          {/* 4. Text "LIMITED TIME" */}
          <g transform={`translate(0, ${textY}) scale(${textScale})`} opacity={textOpacity} style={{ transition: "none" }}>
            {/* Soft backdrop glow to enhance text legibility */}
            <text
              x={0}
              y={0}
              fill={primaryColor}
              fontFamily={getFontFamily()}
              fontSize={110 * s}
              fontWeight={900}
              letterSpacing="0.05em"
              textAnchor="middle"
              alignmentBaseline="middle"
              filter="url(#heavyGlow)"
              opacity={0.7}
              style={{ transition: "none" }}
            >
              {textContent}
            </text>
            <text
              x={0}
              y={0}
              fill={textColor}
              fontFamily={getFontFamily()}
              fontSize={110 * s}
              fontWeight={900}
              letterSpacing="0.05em"
              textAnchor="middle"
              alignmentBaseline="middle"
              style={{ transition: "none" }}
            >
              {textContent}
            </text>
          </g>

          {/* 5. Sub-Text "OFFER ENDS SOON" */}
          <g transform={`translate(0, ${subTextY}) scale(${textScale})`} opacity={textOpacity} style={{ transition: "none" }}>
            <text
              x={0}
              y={0}
              fill={accentColor}
              fontFamily={getFontFamily()}
              fontSize={42 * s}
              fontWeight={700}
              letterSpacing="0.32em"
              textAnchor="middle"
              alignmentBaseline="middle"
              filter="url(#glow)"
              opacity={0.65}
              style={{ transition: "none" }}
            >
              {subtextContent}
            </text>
            <text
              x={0}
              y={0}
              fill={accentColor}
              fontFamily={getFontFamily()}
              fontSize={42 * s}
              fontWeight={700}
              letterSpacing="0.32em"
              textAnchor="middle"
              alignmentBaseline="middle"
              style={{ transition: "none" }}
            >
              {subtextContent}
            </text>
          </g>

        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default AnimatedLinkScene;